export function useIconHydration() {
    const hydrateIcons = (container: HTMLElement | null) => {
        if (!container) return;

        const icons = container.querySelectorAll('span[data-type="icon"]');

        icons.forEach(el => {
            if (!(el instanceof HTMLElement)) return;

            // Check if already hydrated
            if (el.dataset.hydrated) return;

            const name = el.getAttribute('name');
            if (!name) return;

            const IconComponent = iconMap[name] || iconMap.Circle;

            // Collect styles from attributes
            // Note: attributes in HTML might be lowercase, but Tiptap should preserve them if possible
            // We'll check standard names
            const size = el.getAttribute('size') || '1em';
            const color = el.getAttribute('color') || 'currentColor';
            const strokeWidth = el.getAttribute('strokeWidth') || el.getAttribute('strokewidth') || 2;
            const rotate = el.getAttribute('rotate') || 0;
            const backgroundColor = el.getAttribute('backgroundColor') || el.getAttribute('backgroundcolor');
            const borderRadius = el.getAttribute('borderRadius') || el.getAttribute('borderradius') || '0px';
            const padding = el.getAttribute('padding') || '0px';
            const opacity = el.getAttribute('opacity') || 1;

            // Apply wrapper styles to the span itself
            el.style.display = 'inline-block';
            el.style.verticalAlign = 'middle';
            el.style.lineHeight = '0'; // Fix vertical alignment issues
            if (backgroundColor) el.style.backgroundColor = backgroundColor;
            if (borderRadius) el.style.borderRadius = borderRadius;
            if (padding) el.style.padding = padding;
            if (rotate) el.style.transform = `rotate(${rotate}deg)`;
            if (opacity) el.style.opacity = String(opacity);

            // Create vnode
            const vnode = h(IconComponent as any, {
                size: size,
                color: color,
                strokeWidth: strokeWidth,
            });

            // Render into the element
            render(vnode, el);

            // Mark as hydrated
            el.dataset.hydrated = 'true';
        });
    };

    return { hydrateIcons };
}

import { logger } from '@/utils/logger';
import { ref, onMounted, onUnmounted, computed } from 'vue';
import { useRouter } from 'vue-router';
import { useAuthStore } from '@/modules/Core/stores/auth';
// import { useSystemError } from '@/composables/useSystemError';
import { triggerVaporLock } from '@/services/api';
import api from '@/services/api';

export function useSessionTimeout() {
    const router = useRouter();
    const authStore = useAuthStore();

    // Delayed initialization to avoid dual-import warnings
    const showError = async (params: any) => {
        const { useSystemError } = await import('@/composables/useSystemError');
        const { showError: triggerError } = useSystemError();
        triggerError(params);
    };

    // Session configuration (in seconds)
    const SESSION_LIFETIME = parseInt(import.meta.env.VITE_SESSION_LIFETIME || '28800'); // 8 hours default
    const WARNING_TIME = 300; // Show warning 5 minutes before expiry

    // State
    const isWarningVisible = ref(false);
    const timeRemaining = ref(WARNING_TIME);
    const lastActivityTime = ref(Date.now());

    // Timers
    let warningTimer: ReturnType<typeof setTimeout> | null = null;
    let countdownTimer: ReturnType<typeof setInterval> | null = null;
    let activityCheckTimer: ReturnType<typeof setInterval> | null = null;

    // Computed
    const sessionExpiryTime = computed(() => {
        return lastActivityTime.value + (SESSION_LIFETIME * 1000);
    });

    const timeUntilExpiry = computed(() => {
        return Math.max(0, Math.floor((sessionExpiryTime.value - Date.now()) / 1000));
    });

    const isAuthenticated = computed(() => authStore.isAuthenticated);

    // Activity tracking
    const trackActivity = () => {
        if (!isAuthenticated.value) return;

        lastActivityTime.value = Date.now();
        resetTimers();
    };

    // Event listeners for user activity
    const activityEvents = ['mousedown', 'keypress', 'scroll', 'touchstart', 'click'];

    const setupActivityListeners = () => {
        activityEvents.forEach(event => {
            window.addEventListener(event, trackActivity, { passive: true });
        });
    };

    const removeActivityListeners = () => {
        activityEvents.forEach(event => {
            window.removeEventListener(event, trackActivity);
        });
    };

    // Timer management
    const startWarningTimer = () => {
        clearWarningTimer();

        if (!isAuthenticated.value) return;

        const timeUntilWarning = (SESSION_LIFETIME - WARNING_TIME) * 1000;

        warningTimer = setTimeout(() => {
            showWarning();
        }, timeUntilWarning);
    };

    const clearWarningTimer = () => {
        if (warningTimer) {
            clearTimeout(warningTimer);
            warningTimer = null;
        }
    };

    const startCountdownTimer = () => {
        clearCountdownTimer();

        countdownTimer = setInterval(() => {
            if (timeRemaining.value > 0) {
                timeRemaining.value--;
            } else {
                handleTimeout();
            }
        }, 1000);
    };

    const clearCountdownTimer = () => {
        if (countdownTimer) {
            clearInterval(countdownTimer);
            countdownTimer = null;
        }
    };

    // Heartbeat logic
    const HEARTBEAT_INTERVAL = 30 * 1000; // Check every 30 seconds for faster detection
    let heartbeatTimer: ReturnType<typeof setInterval> | null = null;

    const startHeartbeat = () => {
        clearHeartbeat();
        if (!isAuthenticated.value) return;

        heartbeatTimer = setInterval(async () => {
            // Early exit if session is already dead to prevent redundant calls/loops
            if (window.__isSessionTerminated) {
                stopAllTimers();
                return;
            }

            try {
                // Lightweight check to validate session
                await api.get('/user', { _skipManualRedirect: true } as Record<string, unknown>);
            } catch (error: unknown) {
                const err = error as { response?: { status?: number } };
                // Double check flag to prevent race conditions with api.js interceptor
                if (window.__isSessionTerminated) {
                    stopAllTimers();
                    return;
                }

                // If it's a session error (401, 403, or 419)
                const status = err.response?.status;
                if (status === 401 || status === 403 || status === 419) {
                    // Stop everything instantly via Vapor Lock
                    triggerVaporLock();

                    // Stop heartbeat and cleanup locally
                    stopAllTimers();

                    // Force update auth store state to prevent loops
                    authStore.clearAuth();

                    // Logic: Concurrent because it's a heartbeat failure
                    const reason = 'concurrent';

                    // Use modal instead of hard redirect
                    showError({
                        code: status || 419,
                        title: 'Session Expired',
                        message: 'Your session has expired due to concurrent login.',
                        description: 'Please login again to continue.',
                        reason: reason,
                        redirect: router.currentRoute.value.fullPath
                    });
                }
            }
        }, HEARTBEAT_INTERVAL);
    };

    const clearHeartbeat = () => {
        if (heartbeatTimer) {
            clearInterval(heartbeatTimer);
            heartbeatTimer = null;
        }
    };

    const startActivityCheckTimer = () => {
        clearActivityCheckTimer();

        // Check every 30 seconds if session should show warning
        activityCheckTimer = setInterval(() => {
            if (!isAuthenticated.value) {
                stopAllTimers();
                return;
            }

            const timeLeft = timeUntilExpiry.value;

            if (timeLeft <= 0) {
                handleTimeout();
            } else if (timeLeft <= WARNING_TIME && !isWarningVisible.value) {
                showWarning();
            }
        }, 30000); // Check every 30 seconds
    };

    const clearActivityCheckTimer = () => {
        if (activityCheckTimer) {
            clearInterval(activityCheckTimer);
            activityCheckTimer = null;
        }
    };

    const stopAllTimers = () => {
        clearWarningTimer();
        clearCountdownTimer();
        clearActivityCheckTimer();
        clearHeartbeat();
    };

    const resetTimers = () => {
        if (!isWarningVisible.value) {
            startWarningTimer();
            // No need to reset heartbeat on activity, it should run independently
        }
    };

    // Warning modal
    const showWarning = () => {
        if (!isAuthenticated.value) return;

        isWarningVisible.value = true;
        timeRemaining.value = timeUntilExpiry.value;
        startCountdownTimer();
    };

    const hideWarning = () => {
        isWarningVisible.value = false;
        clearCountdownTimer();
        timeRemaining.value = WARNING_TIME;
    };

    // Actions
    const extendSession = async () => {
        try {
            // Make a lightweight API call to extend the session
            await api.get('/user');

            // Reset activity time
            lastActivityTime.value = Date.now();

            // Hide warning and reset timers
            hideWarning();
            startWarningTimer();

        } catch (error) {
            logger.error('Failed to extend session:', error);
            // If extend fails, likely session already expired
            handleTimeout();
        }
    };

    const handleTimeout = () => {
        // Stop everything via Vapor Lock
        triggerVaporLock();
        stopAllTimers();
        hideWarning();

        // Logout user locally
        localStorage.removeItem('auth_token');
        localStorage.removeItem('user');
        authStore.isAuthenticated = false;

        // Use modal instead of hard redirect
        const currentPath = router.currentRoute.value.fullPath;
        showError({
            code: 419,
            title: 'Session Timeout',
            message: 'Your session has timed out due to inactivity.',
            description: 'Please login again to continue.',
            reason: 'timeout',
            redirect: currentPath !== '/' ? currentPath : '/admin'
        });
    };

    const manualLogout = async () => {
        stopAllTimers();
        hideWarning();
        removeActivityListeners();

        await authStore.logout();
        router.push('/login');
    };

    // Initialization
    const initialize = () => {
        if (!isAuthenticated.value) return;

        setupActivityListeners();
        startWarningTimer();
        startActivityCheckTimer();
        startHeartbeat();
        lastActivityTime.value = Date.now();
    };

    const cleanup = () => {
        stopAllTimers();
        removeActivityListeners();
        hideWarning();
    };

    // Lifecycle hooks
    onMounted(() => {
        initialize();
    });

    onUnmounted(() => {
        cleanup();
    });

    // Watch for auth changes
    const watchAuth = () => {
        const unwatch = authStore.$subscribe((_mutation, state) => {
            if (state.isAuthenticated) {
                initialize();
            } else {
                cleanup();
            }
        });

        onUnmounted(unwatch);
    };

    watchAuth();

    return {
        // State
        isWarningVisible,
        timeRemaining,
        timeUntilExpiry,

        // Actions
        extendSession,
        manualLogout,
        showWarning,
        hideWarning,
        trackActivity,

        // Utilities
        initialize,
        cleanup,
    };
}

import { logger } from '@/utils/logger';
import { defineStore } from 'pinia';
import api from '@/services/api';
import { parseResponse, ensureArray } from '@/utils/responseParser';
import type { CMSState, Content, SiteSettings } from '@/types/cms/cms';

export const useCmsStore = defineStore('cms', {
    state: (): CMSState => ({
        contents: [],
        categories: [],
        tags: [],
        media: [],
        settings: {}, // Store settings by group or flat key-value
        siteSettings: {
            site_name: 'JA-Edu',
            site_description: 'Jejakawan',
            site_url: '',
            admin_email: '',
            site_version: 'v1.0',
            site_logo: '',
            site_favicon: '/favicon.svg'
        },
        currentContent: null,
        loading: false,
        loadingGroups: {}, // To track loading state for specific settings groups
        settingsPromises: {}, // To store promises for ongoing settings group fetches
        publicSettingsPromise: null, // Promise for public settings fetch
        publicSettingsLoaded: false, // Flag to track if public settings were fetched
        themeMode: 'system', // 'light', 'dark', 'system'
        isDarkMode: false,
    }),

    actions: {
        async fetchSettingsGroup(group: string) {
            // If already loading, return existing promise
            if (this.loadingGroups[group]) {
                return this.settingsPromises[group];
            }

            // Mark this group as loading
            this.loadingGroups = { ...this.loadingGroups, [group]: true };

            // Create and store the promise for this fetch operation
            const promise = (async () => {
                try {
                    const response = await api.get(`/admin/cms/settings/group/${group}`);
                    const settingsData = response.data?.data || response.data || {};

                    // Only update if there are actual new keys or changed values to prevent reactive thrashing
                    const hasChanges = Object.entries(settingsData).some(([key, value]) => this.settings[key] !== value);
                    if (hasChanges) {
                        this.settings = { ...this.settings, ...settingsData };
                    }
                    return settingsData;
                }
                catch (error: unknown) {
                    logger.error(`Error fetching ${group} settings:`, error);
                    return {};
                } finally {
                    this.loadingGroups = { ...this.loadingGroups, [group]: false };
                    delete this.settingsPromises[group];
                }
            })();

            this.settingsPromises = { ...this.settingsPromises, [group]: promise };
            return promise;
        },

        async fetchPublicSettings(): Promise<SiteSettings> {
            // Already loaded or marked as failed-once to prevent loops
            if (this.publicSettingsLoaded) {
                return this.siteSettings;
            }

            if (this.publicSettingsPromise) {
                return this.publicSettingsPromise;
            }

            this.publicSettingsPromise = (async () => {
                try {
                    const response = await api.get('/public/settings');

                    // Stability: Check response status and data early
                    if (!response || !response.data) {
                        throw new Error('Empty response from public settings API');
                    }

                    const settingsData = response.data?.data || response.data || {};

                    // Critical Guard: Ensure settingsData is a valid object and not a string (HTML error page)
                    if (typeof settingsData !== 'object' || settingsData === null || Array.isArray(settingsData)) {
                        logger.error('[CMS Store] Invalid public settings response (likely HTML error page):', settingsData);
                        return this.siteSettings;
                    }

                    // Stability: Check for actual differences before triggering reactivity
                    const hasChanges = Object.entries(settingsData).some(([key, value]) => {
                        // @ts-ignore: siteSettings dynamic keys
                        return this.siteSettings[key] !== value;
                    });

                    if (hasChanges) {
                        this.siteSettings = { ...this.siteSettings, ...settingsData };
                    }

                    return this.siteSettings;
                } catch (error: unknown) {
                    logger.error('Error fetching public settings:', error);
                    return this.siteSettings;
                } finally {
                    this.publicSettingsLoaded = true; // Always mark as loaded to prevent loops
                    this.publicSettingsPromise = null;
                }
            })();

            return this.publicSettingsPromise;
        },

        async fetchContents(params: Record<string, unknown> = {}) {
            this.loading = true;
            try {
                const response = await api.get('/ja/contents', { params });
                const { data } = parseResponse(response);
                this.contents = ensureArray(data);
                return { data: this.contents };
            } catch (error: unknown) {
                logger.error('Error fetching contents:', error);
                this.contents = [];
                return { data: [] };
            } finally {
                this.loading = false;
            }
        },

        async fetchContent(slug: string): Promise<Content | null> {
            this.loading = true;
            try {
                const response = await api.get(`/ja/contents/${slug}`);
                this.currentContent = response.data;
                return response.data;
            } catch (error: unknown) {
                logger.error('Error fetching content:', error);
                return null;
            } finally {
                this.loading = false;
            }
        },

        async fetchCategories() {
            try {
                const response = await api.get('/ja/categories');
                const { data } = parseResponse(response);
                this.categories = ensureArray(data);
                return this.categories;
            } catch (error: unknown) {
                logger.error('Error fetching categories:', error);
                this.categories = [];
                return [];
            }
        },

        async fetchTags() {
            try {
                const response = await api.get('/ja/tags');
                const { data } = parseResponse(response);
                this.tags = ensureArray(data);
                return this.tags;
            } catch (error: unknown) {
                logger.error('Error fetching tags:', error);
                this.tags = [];
                return [];
            }
        },

        async initTheme() {
            const THEME_KEY = 'admin-dark-mode';

            // 1. Detect system preference
            const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

            // 2. Load from localStorage or fallback to system
            const saved = localStorage.getItem(THEME_KEY) || 'system';
            this.themeMode = saved as 'light' | 'dark' | 'system';

            // 3. Resolve actual dark mode state
            this.isDarkMode = saved === 'dark' || (saved === 'system' && prefersDark);

            // 4. Apply to document
            this.applyThemeToDocument();

            // 5. Watch for system changes
            window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', (e) => {
                if (this.themeMode === 'system') {
                    this.isDarkMode = e.matches;
                    this.applyThemeToDocument();
                }
            });

            // 6. Try to load from backend (if authenticated)
            await this.loadThemePreferences();
        },

        async loadThemePreferences() {
            if (!localStorage.getItem('auth_token')) return;
            try {
                const response = await api.get('/profile/preferences');
                if (response.data?.success && response.data?.data?.dark_mode) {
                    const backendMode = response.data.data.dark_mode;
                    if (this.themeMode !== backendMode) {
                        this.setThemeMode(backendMode, false); // Don't sync back to backend
                    }
                }
            } catch (error: unknown) {
                const message = error instanceof Error ? error.message : String(error);
                logger.debug('Failed to load theme preferences:', { message });
            }
        },

        async syncThemeWithBackend(mode: string) {
            if (!localStorage.getItem('auth_token')) return;
            try {
                await api.put('/profile/preferences', { dark_mode: mode });
            } catch (error: unknown) {
                const message = error instanceof Error ? error.message : String(error);
                logger.debug('Theme sync failed:', { message });
            }
        },

        setThemeMode(mode: 'light' | 'dark' | 'system', syncToBackend = true) {
            const THEME_KEY = 'admin-dark-mode';

            // Add no-transitions class to prevent flashing
            document.documentElement.classList.add('no-transitions');

            this.themeMode = mode;
            localStorage.setItem(THEME_KEY, mode);

            const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
            this.isDarkMode = mode === 'dark' || (mode === 'system' && prefersDark);

            this.applyThemeToDocument();

            if (syncToBackend) {
                this.syncThemeWithBackend(mode);
            }

            // Remove no-transitions class after short delay
            setTimeout(() => {
                document.documentElement.classList.remove('no-transitions');
            }, 50);
        },

        toggleDarkMode(value?: boolean) {
            // If value is provided (e.g. from a switch), use it. 
            // Otherwise, toggle current state.
            const isDark = value !== undefined ? value : !this.isDarkMode;
            const next = isDark ? 'dark' : 'light';
            this.setThemeMode(next);
        },

        applyThemeToDocument() {
            if (this.isDarkMode) {
                document.documentElement.classList.add('dark');
            } else {
                document.documentElement.classList.remove('dark');
            }
        },
    },
});

import { logger } from '@/utils/logger';
import { defineStore } from 'pinia';
import type { AxiosResponse } from 'axios';
import { isCancel, isAxiosError } from 'axios';
import api, { getCsrfCookie, type ApiRequestConfig } from '@/services/api';
import type { User, Role, AuthState, AuthResponse, LoginCredentials, RegisterData, ResetPasswordData } from '@/types/core/auth';
import { userModelSchema, authResponseSchema } from '@/schemas';

interface ApiErrorResponse {
    message?: string;
    errors?: Record<string, string[]>;
    retry_after?: string | number;
    requires_verification?: boolean;
    user_id?: number | string;
    requires_two_factor?: boolean;
}

export const ROLE_RANKS: Record<string, number> = {
    'super-admin': 100,
    'superadmin': 100,
    'super_admin': 100,
    'supe_admin': 100,
    'kepala-sekolah': 90,
    'admin-sekolah': 90,
    'admin-kurikulum': 85,
    'admin-kesiswaan': 85,
    'admin-sarpras': 85,
    'admin-humas': 85,
    'admin-bk': 85,
    'guru': 70,
    'wali-kelas': 75,
    'admin': 80,
    'editor': 60,
    'admin-osis': 50,
    'author': 40,
    'orang-tua': 30,
    'member': 20,
    'siswa': 20,
};

// Define extended window interface for circuit breaker flags
declare global {
    interface Window {
        __isSessionTerminated?: boolean;
        __is403Blocked?: boolean;
    }
}


export const useAuthStore = defineStore('auth', {
    state: (): AuthState & { initialized: boolean } => ({
        user: null,
        isAuthenticated: false,
        initialized: false,
    }),

    getters: {
        // Helper to calculate role rank from a user object
        getRoleRank: (state) => (user: User | null = null): number => {
            const targetUser = user || state.user;
            if (!targetUser || !targetUser.roles) return 0;

            let maxRank = 0;
            targetUser.roles.forEach((role: Role) => {
                const rank = ROLE_RANKS[role.name] || 0;
                if (rank > maxRank) maxRank = rank;
            });

            return maxRank;
        },

        // Check if current user has at least the specified role level
        isAtLeastRole: (state) => (roleName: string): boolean => {
            if (!state.user || !state.user.roles) return false;

            const minRank = ROLE_RANKS[roleName] || 0;

            let myRank = 0;
            state.user.roles.forEach((role: Role) => {
                const rank = ROLE_RANKS[role.name] || 0;
                if (rank > myRank) myRank = rank;
            });

            return myRank >= minRank;
        },

        // Check if current user has higher rank than another user
        isHigherThan: (state) => (otherUser: User): boolean => {
            if (!otherUser) return true;
            if (!state.user || !state.user.roles) return false;

            // Calculate my rank
            let myRank = 0;
            state.user.roles.forEach((role: Role) => {
                const rank = ROLE_RANKS[role.name] || 0;
                if (rank > myRank) myRank = rank;
            });

            // Calculate other user's rank
            let otherRank = 0;
            if (otherUser.roles) {
                otherUser.roles.forEach((role: Role) => {
                    const rank = ROLE_RANKS[role.name] || 0;
                    if (rank > otherRank) otherRank = rank;
                });
            }

            return myRank > otherRank;
        },

        isAdmin: (state): boolean => {
            if (!state.user || !state.user.roles) return false;
            return state.user.roles.some((role: Role) => 
                role.name === 'admin' || 
                (ROLE_RANKS[role.name] || 0) >= 100
            );
        },

        hasPermission: (state) => (permission: string): boolean => {
            if (!state.user) return false;
            // Super-admin (rank 100) always has all permissions
            if (state.user.roles?.some((role: Role) => (ROLE_RANKS[role.name] || 0) >= 100)) return true;
            return state.user.permissions?.some(perm => perm.name === permission) || false;
        },
    },

    actions: {
        async login(credentials: LoginCredentials): Promise<AuthResponse> {
            try {
                // Ensure CSRF cookie is fresh before login
                await getCsrfCookie();

                const response: AxiosResponse<{ data?: any; user?: User; requires_two_factor?: boolean; user_id?: number | string; message?: string }> = await api.post('/login', credentials, {
                    _schema: authResponseSchema
                } as ApiRequestConfig);
                // Handle different response structures
                const responseData = response.data?.data || response.data;

                // Handle 2FA requirement
                if (responseData && responseData.requires_two_factor) {
                    return {
                        success: true,
                        requiresTwoFactor: true,
                        userId: responseData.user_id,
                        message: response.data.message
                    };
                }

                if (responseData && responseData.user) {
                    this.setAuth(responseData as { user: User });
                    return { success: true, data: responseData };
                } else {
                    throw new Error('Invalid response format from server');
                }
            } catch (error: unknown) {
                // Handle different error statuses
                const axiosError = isAxiosError(error) ? error : null;
                const errorData = (axiosError?.response?.data as ApiErrorResponse) || {};
                const errors = errorData.errors || {};
                const status = axiosError?.response?.status;
                const headers = axiosError?.response?.headers || {};

                // Handle rate limiting (429)
                if (status === 429) {
                    // Try to get retry-after from various sources
                    let retryAfter = 60; // Default 60 seconds

                    // Try from response body first
                    if (errorData.retry_after) {
                        retryAfter = parseInt(String(errorData.retry_after), 10);
                    }
                    // Try from headers (axios lowercases header names)
                    else if (headers['retry-after']) {
                        retryAfter = parseInt(String(headers['retry-after']), 10);
                    }

                    const retryAfterSeconds = retryAfter;
                    const retryAfterMinutes = Math.ceil(retryAfterSeconds / 60);

                    return {
                        success: false,
                        message: `Too many login attempts. Please try again in ${retryAfterMinutes} minute${retryAfterMinutes > 1 ? 's' : ''}.`,
                        errors: {},
                        rateLimited: true,
                        retryAfter: retryAfterSeconds,
                    };
                }

                // Handle different error statuses
                if (status === 403) {
                    // Email not verified
                    return {
                        success: false,
                        message: errorData.message || 'Please verify your email address before logging in.',
                        errors: {},
                        requiresVerification: errorData.requires_verification || false,
                    };
                }

                // Extract first error message if available
                let errorMessage = errorData.message;
                if (!errorMessage && errors.email && Array.isArray(errors.email) && errors.email.length > 0) {
                    errorMessage = errors.email[0];
                } else if (!errorMessage && errors.password && Array.isArray(errors.password) && errors.password.length > 0) {
                    errorMessage = errors.password[0];
                } else if (!errorMessage) {
                    errorMessage = 'Login failed. Please check your credentials.';
                }

                return {
                    success: false,
                    message: errorMessage,
                    errors: errors,
                };
            }
        },

        async register(userData: RegisterData): Promise<AuthResponse> {
            try {
                // Ensure CSRF cookie is fresh before register
                await getCsrfCookie();

                const response: AxiosResponse<{ user: User }> = await api.post('/register', userData);
                this.setAuth(response.data);
                return { success: true, data: response.data };
            } catch (error: unknown) {
                const axiosError = isAxiosError(error) ? error : null;
                const responseData = (axiosError?.response?.data as ApiErrorResponse) || {};
                return {
                    success: false,
                    message: responseData.message || 'Registration failed',
                    errors: responseData.errors,
                };
            }
        },

        async logout() {
            try {
                // Skip 401 handler redirect - logout is intentionally ending session
                await api.post('/logout', {}, { _skipManualRedirect: true } as ApiRequestConfig);
            } catch (error: unknown) {
                // Silence session errors (401/419) and cancellations during logout
                // These are expected if the session is already terminated.
                const axiosError = isAxiosError(error) ? error : null;
                const status = axiosError?.response?.status;

                const isSilentError = status === 401 || status === 419 || isCancel(error);

                if (!isSilentError) {
                    logger.error('Logout error:', error);
                }
            } finally {
                this.clearAuth();
                // Reset all circuit breaker flags
                if (typeof window !== 'undefined') {
                    window.__isSessionTerminated = false;
                    window.__is403Blocked = false;
                }

                // Redirect to homepage after logout
                window.location.href = '/';
            }
        },

        async fetchUser(): Promise<AuthResponse> {
            try {
                const response: AxiosResponse<{ data?: User } | User> = await api.get('/user', {
                    _schema: userModelSchema
                } as ApiRequestConfig);
                const userData = (response.data as any)?.data || response.data;
                this.user = userData as User;
                this.isAuthenticated = true;
                // Update localStorage
                if (userData) {
                    this.setAuth({ user: userData as User });
                }
                return { success: true, data: { user: userData as User } };
            } catch (error: unknown) {
                const axiosError = isAxiosError(error) ? error : null;
                const status = axiosError?.response?.status;

                // If it's a 403 or 503, it might be maintenance mode/WAF block.
                // We should NOT clear auth immediately, as we want to preserve the isAdmin state 
                // for the frontend bypass logic.
                if (status !== 403 && status !== 503) {
                    this.clearAuth();
                }

                const responseData = (axiosError?.response?.data as ApiErrorResponse) || {};
                return { success: false, message: responseData.message };
            }
        },

        async forgotPassword(data: { email: string; captcha_token?: string; captcha_answer?: string }): Promise<AuthResponse> {
            try {
                const response: AxiosResponse<{ message: string }> = await api.post('/forgot-password', data);
                return { success: true, message: response.data.message };
            } catch (error: unknown) {
                const axiosError = isAxiosError(error) ? error : null;
                const responseData = (axiosError?.response?.data as ApiErrorResponse) || {};
                return {
                    success: false,
                    message: responseData.message || 'Failed to send reset link',
                };
            }
        },

        async resetPassword(data: ResetPasswordData): Promise<AuthResponse> {
            try {
                const response: AxiosResponse<{ message: string }> = await api.post('/reset-password', data);
                return { success: true, message: response.data.message };
            } catch (error: unknown) {
                const axiosError = isAxiosError(error) ? error : null;
                const responseData = (axiosError?.response?.data as ApiErrorResponse) || {};
                return {
                    success: false,
                    message: responseData.message || 'Password reset failed',
                    errors: responseData.errors,
                };
            }
        },

        setAuth(data: { user: User }) {
            this.user = data.user;
            this.isAuthenticated = true;
            localStorage.setItem('user', JSON.stringify(data.user));
            // Reset circuit breaker flags on successful auth
            if (typeof window !== 'undefined') {
                window.__isSessionTerminated = false;
                window.__is403Blocked = false;
            }
        },

        clearAuth() {
            this.user = null;
            this.isAuthenticated = false;
            localStorage.removeItem('user');
        },

        initAuth() {
            if (this.initialized) return;
            this.initialized = true;

            try {
                const user = localStorage.getItem('user');
                if (user) {
                    // Try to parse user JSON, clear if invalid
                    try {
                        const parsedUser = JSON.parse(user);
                        if (parsedUser && typeof parsedUser === 'object') {
                            this.user = parsedUser;
                            this.isAuthenticated = true;
                        } else {
                            this.clearAuth();
                        }
                    } catch (parseError) {
                        // Invalid JSON in localStorage, clear it
                        if (import.meta.env.DEV) {
                            logger.warning('Invalid user data in localStorage, clearing:', parseError);
                        }
                        this.clearAuth();
                    }
                }
            } catch (error) {
